INSERT INTO journal_blueprints(id,name,description,prompts) VALUES
('daily-reflection','Daily Reflection','A balanced look at your day','[{"id":"day","text":"How was my day?"},{"id":"well","text":"What went well?"},{"id":"better","text":"What could have gone better?"},{"id":"learned","text":"What did I learn?"},{"id":"tomorrow","text":"What will I improve tomorrow?"}]'::jsonb),
('habit-review','Habit Review','Notice what supports your routines','[{"id":"completed","text":"Which habits did I complete?"},{"id":"missed","text":"Which habits did I miss, and why?"},{"id":"helped","text":"What helped me stay consistent?"},{"id":"obstacles","text":"What obstacles affected my routine?"},{"id":"adjustment","text":"What is one adjustment I can make?"}]'::jsonb),
('goal-progress','Goal Progress Review','Connect today with a longer goal','[{"id":"goal","text":"Which goal did I make progress toward?"},{"id":"action","text":"What action contributed to that progress?"},{"id":"blocked","text":"What blocked me?"},{"id":"next","text":"What is the next practical step?"}]'::jsonb),
('gratitude-wellbeing','Gratitude and Well-being','Reflect on energy and care','[{"id":"grateful","text":"What am I grateful for today?"},{"id":"energized","text":"What gave me energy?"},{"id":"drained","text":"What drained my energy?"},{"id":"better","text":"What would help me feel better tomorrow?"}]'::jsonb),
('planning-tomorrow','Planning Tomorrow','Make a practical plan','[{"id":"priorities","text":"What are my most important priorities?"},{"id":"habits","text":"Which habits should I prioritize?"},{"id":"goal","text":"What is the next action toward my main goal?"},{"id":"obstacles","text":"What potential obstacles should I prepare for?"}]'::jsonb);
